"""Independent 2025 scenario values and adversarial semantic/provenance checks."""
import math
from semantic_query_engine import QueryEngine, ROOT
from semantic_question_suite import pointer
from test_semantic_query_engine import rejected
import semantic_query_municipal_tax_adapters as t

# Transcribed reviewed scenario cells, not outputs generated by the adapter.
TARI = {'046005':422.94,'046013':475.73,'046018':542.51,'046024':356.11,'046028':502.22,'046030':365.31,'046033':417.86}
IMU = {'046005':1140,'046013':1060,'046018':1060,'046024':1060,'046028':1140,'046030':1060,'046033':1140}
IRPEF = {'046005':(82.5,144.5,284.5),'046013':(0,153,283),'046018':(160,240,400),'046024':(150,225,375),'046028':(160,240,400),'046030':(160,240,400),'046033':(150,225,375)}


def query(key,op='compare',**s): return dict(operation=op,selectors=[dict(metric=key,**s)])


def cells():
    yield t.TARI,'total',TARI
    yield t.IMU,'total',IMU
    yield t.IMU,'ratePercent',{c:v/1000 for c,v in IMU.items()}
    yield t.IRPEF,'total',{c:v[0] for c,v in IRPEF.items()}
    for i,n in enumerate(t.SCENARIOS): yield t.IRPEF,'income:'+str(n),{c:v[i] for c,v in IRPEF.items()}
    yield t.IRPEF,'effectiveRate:20000',{c:v[0]/200 for c,v in IRPEF.items()}


def regressions(path):
    e=QueryEngine(path,layer='effective');cat=e.catalog
    for key,dim,expected in cells():
        r=e.query(query(key,dimension=dim));assert r['status']=='computed',r
        for o in r['observations']:
            assert math.isclose(o['value'],expected[o['geography']],abs_tol=1e-9) and o['period']=='2025'
            assert pointer(cat,o['provenance'][0]['valuePointer'])==o['value']
            snap,_=e.file(t.PATHS[key]);native=pointer(snap,o['provenance'][1]['recordPointer'])
            assert math.isclose(native/(200 if dim=='effectiveRate:20000' else 1),o['value'],abs_tol=1e-9)
            assert not o['dataUnavailable'] and not o['notApplicable']
            assert o['unit']==('percent' if dim in ('ratePercent','effectiveRate:20000') else t.UNITS[key])
        rank=e.query(query(key,'rank',dimension=dim));assert rank['status']=='computed',rank
        assert [x['geography'] for x in rank['result']['ranking']]==sorted(expected,key=lambda c:(-expected[c],c))
        for period in ('2024','2026'):
            rejected(e,query(key,dimension=dim,periods=[period]),'municipal_tax_period_not_frozen')
        for op in ('series','absolute_change','relative_change','percentage_points','trend'):
            rejected(e,query(key,op,dimension=dim,towns=['046018']),'municipal_tax_single_snapshot_no_history')
        rejected(e,query(key,'weighted_ratio',dimension=dim),'municipal_tax_scenarios_not_additive_population')
        rejected(e,query(key,'anomaly',dimension=dim),'municipal_tax_peer_anomaly_not_reviewed')
        rejected(e,dict(query(key,'benchmark_gap',dimension=dim,towns=['046018']),benchmark='tuscany'),'municipal_tax_geographic_benchmark_not_frozen')
    for key in t.KEYS:
        for pair in ([dict(metric=key),dict(metric='population')],[dict(metric='population'),dict(metric=key)]):
            rejected(e,dict(operation='correlation',selectors=pair,axis='municipalities',method='pearson',purpose='descriptive'),'municipal_tax_pair_not_jointly_reviewed')
        mutations=[lambda m:m['meta'].update(year='2026'),lambda m:m['meta'].update(unit='percent'),lambda m:m['meta'].update(polarity='positive'),lambda m:m.update(sourceUrl='https://example.com'),lambda m:m['method'].update(formula='different'),lambda m:m['rows'][0].update(value=False),lambda m:m['rows'][0].update(benchmarkValue=1),lambda m:m['rows'][0].update(town='Unknown'),lambda m:m['rows'][0].update(slug='unknown'),lambda m:m['rows'][0].update(code='046005'),lambda m:m['rows'][0].update(dataUnavailable=True),lambda m:m['rows'][0].update(normalized={'value':1}),lambda m:m['rows'][0].update(ratioComponents={'numerator':1}),lambda m:m['rows'][0]['series']['values'].__setitem__(0,False),lambda m:m['aggregate'].update(value=999),lambda m:m['aggregate'].update(label='Consolidated Versilia'),lambda m:m['meta'].update(benchmark={'tuscany':1})]
        if key==t.IRPEF: mutations += [lambda m:m['rows'][0]['parts'][1].update(value=1),lambda m:m['rows'][0]['municipalIrpefScaleCompanion'].update(normalized=1),lambda m:m['rows'][0]['componentSeries']['30.000 €']['years'].__setitem__(0,2024)]
        if key==t.TARI: mutations += [lambda m:m['rows'][0]['tariffDetail'].update(equalization2025=0)]
        if key==t.IMU: mutations += [lambda m:m['rows'][0].update(ratePercent=1)]
        for mutation in mutations:
            g=QueryEngine(path,layer='effective');mutation(g._catalog['metrics'][key]);assert g.query(query(key))['status']=='not_computable'
        for field in ('path','sha256'):
            g=QueryEngine(path,layer='effective');_,ref=g.file(t.PATHS[key]);ref[field]='changed';assert g.query(query(key))['status']=='not_computable'
        g=QueryEngine(path,layer='effective');native,_=g.file(t.PATHS[key]);native['schemaVersion']=999;assert g.query(query(key))['status']=='not_computable'
    # Exemption threshold is a switch on whole taxable income, not a deductible band.
    raw,_=e.file(t.RULES);rules=raw['municipalIrpef']['towns']
    assert t.irpef_amount(rules['Forte dei Marmi'],20000)==0
    assert 15000*.0035+5000*.006==82.5  # Camaiore: all brackets taxable after exemption threshold.
    assert 28000*.005+2000*.0065==153  # Forte: exemption doesn't subtract 20000 from base.
    print('Municipal tax adapters PASS: 56 fixed cells, 2025 periods, zero/exemption and ties, provenance and adversarial guards')


if __name__=='__main__':regressions(ROOT/'dist/data/site-data.json')
